67	/**
68	 * @author Vitaliy Fedoriv
69	 */
70	
71	@RestController
72	@CrossOrigin(exposedHeaders = "errors, content-type")
73	@RequestMapping("/api")
74	public class OwnerRestControllerV1 implements OwnersApi {
75	
76	    private final ClinicService clinicService;
77	
78	    private final OwnerMapper ownerMapper;
79	
80	    private final PetMapper petMapper;
81	
82	    private final VisitMapper visitMapper;
83	
84	    private final OwnerFieldsValidator ownerFieldsValidator;
85	
86	    private final PostcodeValidator postcodeValidator;
87	
88	    private final HouseholdDuplicateValidator householdDuplicateValidator;
89	
90	    private final IdentityDuplicateValidator identityDuplicateValidator;
91	
92	    private final HouseholdIdGenerator householdIdGenerator;
93	
94	    private final TelephoneNormalizer telephoneNormalizer;
95	
96	    private final EmailNormalizer emailNormalizer;
97	
98	    private final AddressNormalizer addressNormalizer;
99	
100	    private final CustomerCodeGenerator customerCodeGenerator;
101	
102	    private final NamesakeCounter namesakeCounter;
103	
104	    private final BulkSignupWarningEvaluator bulkSignupWarningEvaluator;
105	
106	    private final OwnerAuditLogger ownerAuditLogger;
107	
108	    public OwnerRestControllerV1(ClinicService clinicService,
109	                                 OwnerMapper ownerMapper,
110	                                 PetMapper petMapper,
111	                                 VisitMapper visitMapper,
112	                                 OwnerFieldsValidator ownerFieldsValidator,
113	                                 PostcodeValidator postcodeValidator,
114	                                 HouseholdDuplicateValidator householdDuplicateValidator,
115	                                 IdentityDuplicateValidator identityDuplicateValidator,
116	                                 HouseholdIdGenerator householdIdGenerator,
117	                                 TelephoneNormalizer telephoneNormalizer,
118	                                 EmailNormalizer emailNormalizer,
119	                                 AddressNormalizer addressNormalizer,
120	                                 CustomerCodeGenerator customerCodeGenerator,
121	                                 NamesakeCounter namesakeCounter,
122	                                 BulkSignupWarningEvaluator bulkSignupWarningEvaluator,
123	                                 OwnerAuditLogger ownerAuditLogger) {
124	        this.clinicService = clinicService;
125	        this.ownerMapper = ownerMapper;
126	        this.petMapper = petMapper;
127	        this.visitMapper = visitMapper;
128	        this.ownerFieldsValidator = ownerFieldsValidator;
129	        this.postcodeValidator = postcodeValidator;
130	        this.householdDuplicateValidator = householdDuplicateValidator;
131	        this.identityDuplicateValidator = identityDuplicateValidator;
132	        this.householdIdGenerator = householdIdGenerator;
133	        this.telephoneNormalizer = telephoneNormalizer;
134	        this.emailNormalizer = emailNormalizer;
135	        this.addressNormalizer = addressNormalizer;
136	        this.customerCodeGenerator = customerCodeGenerator;
137	        this.namesakeCounter = namesakeCounter;
138	        this.bulkSignupWarningEvaluator = bulkSignupWarningEvaluator;
139	        this.ownerAuditLogger = ownerAuditLogger;
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
145	        Collection<Owner> owners;
146	        if (lastName != null) {
147	            owners = this.clinicService.findOwnerByLastName(lastName);
148	        } else {
149	            owners = this.clinicService.findAllOwners();
150	        }
151	        if (owners.isEmpty()) {
152	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
153	        }
154	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
160	        Owner owner = this.clinicService.findOwnerById(ownerId);
161	        if (owner == null) {
162	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
163	        }
164	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Override
169	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
170	        if (ownerFieldsDto != null) {
171	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
172	        }
173	        List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFieldsDto);
174	        if (!missingFields.isEmpty()) {
175	            throw new MissingOwnerFieldsException(missingFields);
176	        }
177	        HttpHeaders headers = new HttpHeaders();
178	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
179	        Collection<Owner> sameLastName =
180	            this.clinicService.findOwnersByLastNameIgnoreCase(owner.getLastName());
181	        owner.setNamesakeCount(namesakeCounter.count(owner, sameLastName));
182	        List<Owner> householdMembers = assignHousehold(owner, ownerFieldsDto, sameLastName);
183	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
184	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
185	        postcodeValidator.validate(owner.getPostcode(), owner.getCity());
186	        rejectIfDuplicateIdentity(owner);
187	        joinHousehold(owner, householdMembers);
188	        if (owner.getRegistrationDate() == null) {
189	            owner.setRegistrationDate(LocalDate.now());
190	        }
191	        owner.setRegistrationDate(BusinessDayResolver.toBusinessDay(owner.getRegistrationDate()));
192	        LocalDate registrationDate = owner.getRegistrationDate();
193	        long ownersRegisteredToday = clinicService.countOwnersByRegistrationDate(registrationDate);
194	        if (ownersRegisteredToday >= DailyOwnerLimitException.MAX_OWNERS_PER_DAY) {
195	            throw new DailyOwnerLimitException(registrationDate);
196	        }
197	        owner.setBulkSignupWarning(bulkSignupWarningEvaluator.isBulkSignup(ownersRegisteredToday));
198	        long cityOwnerCount = clinicService.countOwnersByCity(owner.getCity());
199	        if (cityOwnerCount >= CityOwnerLimitException.MAX_OWNERS_PER_CITY) {
200	            throw new CityOwnerLimitException(owner.getCity());
201	        }
202	        String region = LocalityResolver.localityOf(owner.getPostcode(), owner.getCity());
203	        owner.setCustomerCode(customerCodeGenerator.generate(
204	            region, owner.getTelephone(), owner.getLastName()));
205	        this.clinicService.saveOwner(owner);
206	        ownerAuditLogger.ownerCreated(owner);
207	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
208	        headers.setLocation(UriComponentsBuilder.newInstance()
209	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
210	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
211	    }
212	
213	    /**
214	     * Assigns the household attributes of an owner about to be created, without touching any
215	     * existing owner. The new owner's household size after this create is recorded (the existing
216	     * members that share its last name and address, compared case-insensitively with collapsed
217	     * whitespace, plus the owner itself). When the owner shares a household with an existing one
218	     * and the request opted in via {@code sharesHousehold}, the new owner is stamped with the
219	     * household's stable {@code householdId}.
220	     *
221	     * <p>Sharing a household is no longer a rejection in itself: duplicate detection is decided
222	     * solely by the derived identity key in {@link #rejectIfDuplicateIdentity(Owner)}. Because the
223	     * telephone is part of that key, household members with different telephones are all allowed.
224	     *
225	     * @return the existing household members that the new owner joins (empty when it starts a new
226	     *         household or does not opt in)
227	     */
228	    private List<Owner> assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto, Collection<Owner> sameLastName) {
229	        List<Owner> members = householdDuplicateValidator.findHouseholdMembers(owner, sameLastName);
230	        owner.setHouseholdSize(members.size() + 1);
231	        if (members.isEmpty() || !Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
232	            return List.of();
233	        }
234	        owner.setHouseholdId(householdIdGenerator.generate(owner));
235	        return members;
236	    }
237	
238	    /**
239	     * Stamps every existing member the new owner joins with the owner's {@code householdId}, so
240	     * the whole household shares one identifier. Called only once the owner has cleared duplicate
241	     * detection, so no existing owner is mutated for a create that is going to be rejected.
242	     */
243	    private void joinHousehold(Owner owner, List<Owner> members) {
244	        String householdId = owner.getHouseholdId();
245	        for (Owner member : members) {
246	            if (!householdId.equals(member.getHouseholdId())) {
247	                member.setHouseholdId(householdId);
248	                this.clinicService.saveOwner(member);
249	            }
250	        }
251	    }
252	
253	    /**
254	     * Rejects the owner when its whole derived {@link IdentityKey} already belongs to another
255	     * owner. A full-key match requires an equal telephone, so only owners with the same
256	     * (already normalized) telephone are compared.
257	     *
258	     * @throws DuplicateIdentityException if an existing owner shares the new owner's identity key
259	     */
260	    private void rejectIfDuplicateIdentity(Owner owner) {
261	        Collection<Owner> sameTelephone = this.clinicService.findOwnersByTelephone(owner.getTelephone());
262	        if (identityDuplicateValidator.isDuplicate(owner, sameTelephone)) {
263	            throw new DuplicateIdentityException(IdentityKey.of(owner));
264	        }
265	    }
266	
267	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
268	    @Override
269	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
270	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
271	        if (currentOwner == null) {
272	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
273	        }
274	        currentOwner.setAddress(ownerFieldsDto.getAddress());
275	        currentOwner.setCity(ownerFieldsDto.getCity());
276	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
277	        currentOwner.setLastName(ownerFieldsDto.getLastName());
278	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
279	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
280	        this.clinicService.saveOwner(currentOwner);
281	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
282	    }
283	
284	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
285	    @Transactional
286	    @Override
287	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
288	        Owner owner = this.clinicService.findOwnerById(ownerId);
289	        if (owner == null) {
290	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
291	        }
292	        this.clinicService.deleteOwner(owner);
293	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
294	    }
295	
296	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
297	    @Override
298	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
299	        Owner owner = this.clinicService.findOwnerById(ownerId);
300	        if (owner == null) {
301	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
302	        }
303	        HttpHeaders headers = new HttpHeaders();
304	        Pet pet = petMapper.toPet(petFieldsDto);
305	        owner.setId(ownerId);
306	        pet.setOwner(owner);
307	        pet.getType().setName(null);
308	        this.clinicService.savePet(pet);
309	        PetDto petDto = petMapper.toPetDto(pet);
310	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
311	            .buildAndExpand(pet.getId()).toUri());
312	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
313	    }
314	
315	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
316	    @Override
317	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
318	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
319	        if (currentOwner != null) {
320	            Pet currentPet = this.clinicService.findPetById(petId);
321	            if (currentPet != null) {
322	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
323	                currentPet.setName(petFieldsDto.getName());
324	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
325	                this.clinicService.savePet(currentPet);
326	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
327	            }
328	        }
329	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
330	    }
331	
332	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
333	    @Override
334	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
335	        HttpHeaders headers = new HttpHeaders();
336	        Visit visit = visitMapper.toVisit(visitFieldsDto);
337	        Pet pet = new Pet();
338	        pet.setId(petId);
339	        visit.setPet(pet);
340	        this.clinicService.saveVisit(visit);
341	        VisitDto visitDto = visitMapper.toVisitDto(visit);
342	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
343	            .buildAndExpand(visit.getId()).toUri());
344	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
345	    }
346	
347	
348	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
349	    @Override
350	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
351	        Owner owner = this.clinicService.findOwnerById(ownerId);
352	        if (owner != null) {
353	            Pet pet = owner.getPet(petId);
354	            if (pet != null) {
355	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
356	            }
357	        }
358	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
359	    }
360	}
